 const heights={house:17,tower:58,shop:17,mall:25,clinic:22,social:40,office:67,transit:16};let h=heights[type]||25;const bx=x+.17,by=y+.18,w=type==='tower'?.54:.65,d=type==='office'?.51:.63;
